(async () => {
  var out = { err: '', meta: {}, schema: {}, states: {} };
  var note = function (m) { out.err += '[' + m + ']'; };
  var $ = window.jQuery;
  var D = window.wpforms_dashboard || {};

  function post(data) {
    return new Promise(function (res) {
      $.post(window.ajaxurl, data)
        .done(function (r) { res(r); })
        .fail(function (x, s) { res({ success: false, _fail: s || 'fail' }); });
    });
  }

  // jQuery serializeArray semantics: document order, skip disabled, skip
  // unchecked boxes, later name wins (the checkboxes type renders a hidden "0"
  // before its checkbox "1"). Mirrors widget-settings.min.js p.serialize().
  function serializePopover(pop) {
    var o = {};
    Array.prototype.forEach.call(pop.querySelectorAll('input[name], select[name], textarea[name]'), function (el) {
      if (el.disabled) return;
      if ((el.type === 'checkbox' || el.type === 'radio') && !el.checked) return;
      var nm = el.name;
      if (nm.slice(-2) === '[]') { var k = nm.slice(0, -2); (o[k] = o[k] || []).push(el.value); }
      else o[nm] = el.value;
    });
    return o;
  }

  function txt(el) { return el ? (el.textContent || '').replace(/\s+/g, ' ').trim() : ''; }

  try {
    if (!$) { note('no jQuery'); }
    if (!D.nonce) { note('no wpforms_dashboard.nonce'); }
    if (!window.Chart) { note('no window.Chart'); }

    // ── meta ────────────────────────────────────────────────────────────────
    out.meta.scrollHeight = document.body.scrollHeight;
    out.meta.docScrollHeight = document.documentElement.scrollHeight;
    out.meta.viewport = [window.innerWidth, window.innerHeight];
    out.meta.chartVersion = (window.Chart && window.Chart.version) || '';
    out.meta.hasMoment = typeof window.moment === 'function';
    out.meta.href = window.location.href;

    // wpforms_dashboard is a JS global; capture strips every <script>, so the
    // chart-critical parts of it have to ride on this attribute or the rebuilt
    // charts lose their per-report colours and currency formatting.
    out.meta.localized = {
      i18n: D.i18n || null,
      paymentsColors: D.paymentsColors || null,
      paymentsDecimals: typeof D.paymentsDecimals === 'undefined' ? null : D.paymentsDecimals,
      paymentsNoData: D.paymentsNoData || null,
      paymentsDates: D.paymentsDates || '',
      dateFormat: D.date_format || '',
      flatpickr: D.flatpickr || null,
      readiness: D.readiness || null
    };

    var ebody = document.querySelector('.wpforms-dashboard-widget-entries-body');
    var delim = (D.flatpickr && D.flatpickr.delimiter) || ' - ';
    out.meta.delimiter = delim;
    out.meta.rangeStart = ebody ? ebody.getAttribute('data-range-start') : '';
    out.meta.rangeEnd = ebody ? ebody.getAttribute('data-range-end') : '';
    out.meta.rangeString = (out.meta.rangeStart && out.meta.rangeEnd)
      ? out.meta.rangeStart + delim + out.meta.rangeEnd : '';

    // Canvas census — these are the elements capture is about to rasterize.
    out.meta.canvases = Array.prototype.map.call(document.querySelectorAll('canvas'), function (c) {
      var r = c.getBoundingClientRect();
      return { id: c.id || '', cls: c.className || '', w: Math.round(r.width), h: Math.round(r.height),
               host: c.parentElement ? (c.parentElement.className || c.parentElement.tagName) : '' };
    });

    // data-config payloads stay in the DOM (attributes survive capture); record
    // presence + size only so this attribute does not duplicate them.
    function cfgInfo(sel) {
      var el = document.querySelector(sel);
      if (!el) return null;
      var raw = el.getAttribute('data-config') || '';
      return { present: true, bytes: raw.length };
    }
    out.meta.configs = {
      entries: cfgInfo('.wpforms-dashboard-widget-entries-chart'),
      locations: cfgInfo('.wpforms-dashboard-locations'),
      payments: cfgInfo('.wpforms-dashboard-widget-payments-graph')
    };

    // ── date range: AJAX or reload? Record the real control set. ────────────
    var dform = document.querySelector('.wpforms-overview-top-bar-filter-form');
    out.meta.datepicker = {
      formPresent: !!dform,
      buttonPresent: !!document.querySelector('#wpforms-datepicker-popover-button'),
      buttonText: txt(document.querySelector('#wpforms-datepicker-popover-button')),
      popoverPresent: !!document.querySelector('.wpforms-datepicker-popover'),
      calendarBuilt: !!document.querySelector('.wpforms-datepicker-popover .flatpickr-calendar'),
      // The Pro datepicker submits the form and calls updater.fetchStats() —
      // AJAX + history.pushState, never a navigation. Recorded as evidence.
      submitIsAjax: true,
      presets: Array.prototype.map.call(
        document.querySelectorAll('.wpforms-overview-top-bar-filter-form input[type="radio"]'),
        function (r) {
          return { preset: r.dataset.preset || '', name: r.name, value: r.value,
                   checked: !!r.checked, disabled: !!r.disabled,
                   label: txt(r.closest('label')) };
        })
    };
    var popEl = document.querySelector('.wpforms-datepicker-popover');
    out.states.DP = popEl ? {
      outerHTML: popEl.outerHTML,
      computedDisplay: window.getComputedStyle(popEl).display
    } : null;

    var scRow = document.querySelector('#wpforms-dashboard-stat-cards');
    out.states.S_DEFAULT = scRow ? { outerHTML: scRow.outerHTML } : null;
    if (!scRow) note('no #wpforms-dashboard-stat-cards');

    // ── gear schema per widget (read from the frozen popovers) ──────────────
    var wnames = ['entries', 'payments', 'locations'];
    var roots = {};
    wnames.forEach(function (w) {
      var root = document.querySelector('.wpforms-dashboard-widget[data-widget="' + w + '"]');
      roots[w] = root;
      if (!root) { note('no widget ' + w); out.schema[w] = null; return; }
      var pop = root.querySelector('.wpforms-dashboard-widget-settings');
      out.schema[w] = {
        cog: !!root.querySelector('.wpforms-dashboard-widget-cog'),
        popover: !!pop,
        popoverHiddenAttr: pop ? pop.hasAttribute('hidden') : null,
        saveBtn: !!root.querySelector('.wpforms-dashboard-widget-settings-save'),
        resetBtn: !!root.querySelector('.wpforms-dashboard-widget-settings-reset'),
        resetHidden: root.querySelector('.wpforms-dashboard-widget-settings-reset')
          ? root.querySelector('.wpforms-dashboard-widget-settings-reset').classList.contains('wpforms-hidden') : null,
        selects: pop ? Array.prototype.map.call(pop.querySelectorAll('select[name]'), function (s) {
          return { name: s.name, value: s.value, lockedBy: s.getAttribute('data-locked-by') || '',
                   options: Array.prototype.map.call(s.options, function (o) { return { value: o.value, label: txt(o) }; }) };
        }) : [],
        checklists: pop ? Array.prototype.map.call(pop.querySelectorAll('ul.wpforms-dashboard-widget-settings-list'), function (ul) {
          var first = ul.querySelector('input[type="checkbox"]');
          return { name: first ? first.name : '',
                   minUnchecked: ul.getAttribute('data-min-unchecked'),
                   maxChecked: ul.getAttribute('data-max-checked'),
                   options: Array.prototype.map.call(ul.querySelectorAll('input[type="checkbox"]'), function (c) {
                     return { value: c.value, label: txt(c.closest('label')), checked: c.checked };
                   }) };
        }) : [],
        groups: pop ? Array.prototype.map.call(pop.querySelectorAll('.wpforms-dashboard-widget-settings-group label'), function (l) {
          var c = l.querySelector('input[type="checkbox"]');
          return { name: c ? c.name : '', label: txt(l), checked: c ? c.checked : null };
        }) : [],
        settings: pop ? serializePopover(pop) : null
      };
    });

    // ── entries: forms in the table + graph buttons ─────────────────────────
    var btns = Array.prototype.slice.call(document.querySelectorAll('.wpforms-dashboard-widget-entries-graph-btn'));
    out.meta.forms = btns.map(function (b) {
      var tr = b.closest('tr');
      var nameCell = tr ? tr.querySelector('.wpforms-dashboard-widget-entries-col-form_name, td') : null;
      var entriesCell = tr ? tr.querySelector('.wpforms-dashboard-widget-entries-col-entries') : null;
      return { formId: b.getAttribute('data-form-id'),
               name: txt(nameCell),
               entries: txt(entriesCell) };
    });
    out.meta.graphResetCount = document.querySelectorAll('.wpforms-dashboard-widget-entries-graph-reset').length;
    out.meta.entriesRowCount = document.querySelectorAll('.wpforms-dashboard-widget-entries-table tbody tr, [data-widget="entries"] table tbody tr').length;

    // ── payments tiles ─────────────────────────────────────────────────────
    var tiles = Array.prototype.slice.call(document.querySelectorAll('.wpforms-dashboard-widget-payments-tiles button[data-stats]'));
    out.meta.paymentsTiles = tiles.map(function (t) {
      return { stats: t.getAttribute('data-stats'), selected: t.classList.contains('is-selected'),
               isAmount: t.classList.contains('is-amount'), label: txt(t.querySelector('.statcard-label') || t) };
    });
    out.meta.paymentsRows = document.querySelectorAll('.wpforms-dashboard-widget-payments-table tbody tr').length;

    if (!D.nonce || !$) { document.body.setAttribute('data-wpf-dashboard', JSON.stringify(out)); return 'aborted early: ' + out.err; }

    var nonce = D.nonce;
    var range = out.meta.rangeString;

    function entriesHtml() {
      return post({ action: 'wpforms_dashboard_get_entries_widget_html', nonce: nonce, date: range })
        .then(function (r) {
          if (!r || !r.success) { note('entries_html failed'); return ''; }
          return (r.data && r.data.entries_html) || '';
        });
    }
    function saveEntries(settings) {
      return post({ action: 'wpforms_dashboard_save_widget_settings', nonce: nonce, widget: 'entries', settings: settings });
    }

    var eSchema = out.schema.entries || {};
    var base = eSchema.settings ? JSON.parse(JSON.stringify(eSchema.settings)) : null;
    if (!base) note('no entries popover settings');

    // The entries popover carries exactly one select. Its name is "count", not
    // "number_of_forms" — a name-pattern guess missed it on the first pass, so
    // take the first select rather than matching on the label's wording.
    var numField = (eSchema.selects || [])[0] || null;
    var chartField = (eSchema.groups || []).filter(function (g) { return /graph|chart/i.test(g.name); })[0] || null;
    var listField = (eSchema.checklists || [])[0] || null;
    out.meta.entriesFields = {
      number: numField ? numField.name : '',
      chart: chartField ? chartField.name : '',
      list: listField ? listField.name : ''
    };

    // ── E1: chart scoped to a single form (AJAX; persists — reset later) ────
    out.states.E1 = { forms: [] };
    var pickIds = out.meta.forms.slice(0, 3).map(function (f) { return f.formId; });
    for (var i = 0; i < pickIds.length; i++) {
      var fid = pickIds[i];
      var r1 = await post({ action: 'wpforms_dashboard_entries_chart', nonce: nonce, date: range, form_id: fid });
      if (r1 && r1.success && r1.data) {
        out.states.E1.forms.push({ formId: String(fid), name: (out.meta.forms[i] || {}).name || '', graph: r1.data.graph || [] });
      } else { note('E1 form ' + fid + ' failed'); }
    }
    var rr = await post({ action: 'wpforms_dashboard_entries_chart_reset', nonce: nonce });
    out.states.E1.resetOk = !!(rr && rr.success);

    // ── E2 / E3 / E4: gear saves, each followed by the server re-render ─────
    if (base) {
      if (numField) {
        var s2 = JSON.parse(JSON.stringify(base));
        s2[numField.name] = '3';
        if (listField) s2[listField.name.replace(/\[\]$/, '')] = [''];
        var a2 = await saveEntries(s2);
        out.states.E2 = { ok: !!(a2 && a2.success), settings: s2, entriesHtml: await entriesHtml() };
      } else { note('no entries number field'); }

      if (chartField) {
        var s3 = JSON.parse(JSON.stringify(base));
        s3[chartField.name] = '0';
        if (listField) s3[listField.name.replace(/\[\]$/, '')] = [''];
        var a3 = await saveEntries(s3);
        out.states.E3 = { ok: !!(a3 && a3.success), settings: s3, entriesHtml: await entriesHtml() };
      } else { note('no entries display-chart field'); }

      if (listField && listField.options.length >= 2) {
        // Tick forms that actually appear in the table, not the first two
        // alphabetically — the checklist is alphabetical and its head is
        // developer fixture forms ("Abilities API Doc Test Form"), which would
        // put fixture texture on camera.
        var tableIds = out.meta.forms.map(function (f) { return String(f.formId); });
        var real = listField.options.filter(function (o) { return tableIds.indexOf(String(o.value)) !== -1; });
        var picked = (real.length >= 2 ? real : listField.options).slice(0, 2);
        var s4 = JSON.parse(JSON.stringify(base));
        var lname = listField.name.replace(/\[\]$/, '');
        var chosen = picked.map(function (o) { return o.value; });
        s4[lname] = chosen;
        var a4 = await saveEntries(s4);
        out.states.E4 = { ok: !!(a4 && a4.success), settings: s4, chosen: chosen,
                          labels: picked.map(function (o) { return o.label; }),
                          entriesHtml: await entriesHtml() };
      } else { note('no entries checklist with >=2 options'); }
    }

    // ── E_TOP10 + E_ROWS: enough truth to render ANY reachable gear state ──
    // The gear offers count 3..10 and a checklist capped at 10 of 53 forms, so
    // the reachable state space cannot be harvested combination by combination.
    // That was the v1 defect: only 4 exact combinations were recorded, so 6 of
    // the 8 Number-of-Forms values did nothing on Save. Harvest the top-10
    // table once, plus every form's own row in capped batches, and let the
    // module compose the rest by slicing and filtering — the same approach the
    // locations widget already uses, and what the product itself does.
    function rowsFromHtml(h) {
      var t = document.createElement('div');
      t.innerHTML = h;
      var map = {}, order = [];
      var trs = t.querySelectorAll('.wpforms-dashboard-widget-entries-table tbody tr');
      for (var ri = 0; ri < trs.length; ri++) {
        var btn = trs[ri].querySelector('[data-form-id]');
        if (!btn) continue;
        var fid = String(btn.getAttribute('data-form-id'));
        map[fid] = trs[ri].outerHTML;
        order.push(fid);
      }
      return { map: map, order: order };
    }

    if (base && numField) {
      var sT = JSON.parse(JSON.stringify(base));
      sT[numField.name] = '10';
      if (listField) sT[listField.name.replace(/\[\]$/, '')] = [''];
      var aT = await saveEntries(sT);
      var htmlT = await entriesHtml();
      var pT = rowsFromHtml(htmlT);
      out.states.E_TOP10 = {
        ok: !!(aT && aT.success), settings: sT, entriesHtml: htmlT,
        order: pT.order, rows: pT.map
      };
      if (!pT.order.length) note('E_TOP10 parsed 0 rows');
    } else { note('no entries number field for E_TOP10'); }

    if (base && listField && listField.options.length) {
      var lname2 = listField.name.replace(/\[\]$/, '');
      var allOpts = listField.options.map(function (o) { return String(o.value); });
      var cap = listField.maxChecked || 10;
      var allRows = {}, missed = [];
      for (var b0 = 0; b0 < allOpts.length; b0 += cap) {
        var batch = allOpts.slice(b0, b0 + cap);
        var sB = JSON.parse(JSON.stringify(base));
        sB[lname2] = batch;
        var aB = await saveEntries(sB);
        if (!(aB && aB.success)) { note('E_ROWS batch at ' + b0 + ' failed'); continue; }
        var pB = rowsFromHtml(await entriesHtml());
        for (var k in pB.map) {
          if (Object.prototype.hasOwnProperty.call(pB.map, k)) allRows[k] = pB.map[k];
        }
        for (var bi = 0; bi < batch.length; bi++) {
          if (!allRows[batch[bi]]) missed.push(batch[bi]);
        }
      }
      // A form the server renders no row for (no entries in range) is a real
      // product outcome, not a harvest failure — record it so the module can
      // tell "nothing to show" from "not harvested".
      out.states.E_ROWS = { count: Object.keys(allRows).length, noRow: missed, rows: allRows };
    } else { note('no entries checklist for E_ROWS'); }

    // ── E5: reset to default (also restores the site's own state) ───────────
    var a5 = await post({ action: 'wpforms_dashboard_reset_widget_settings', nonce: nonce, widget: 'entries' });
    out.states.E5 = { ok: !!(a5 && a5.success), settings: (a5 && a5.data && a5.data.settings) || null, entriesHtml: await entriesHtml() };

    // ── P1: payments chart per report (AJAX; does not persist) ──────────────
    out.states.P1 = { reports: {} };
    var pnonce = D.paymentsOverviewNonce || '';
    if (!pnonce) note('no paymentsOverviewNonce');
    var dates = (new URL(window.location.href)).searchParams.get('date') || D.paymentsDates || range;
    out.meta.paymentsDates = dates;
    for (var t = 0; t < out.meta.paymentsTiles.length; t++) {
      var rep = out.meta.paymentsTiles[t].stats;
      var rp = await post({ action: 'wpforms_payments_overview_refresh_chart_dataset_data',
                            report: rep, dates: dates, context: 'dashboard', _ajax_nonce: pnonce });
      if (rp && rp.data && typeof rp.data.data !== 'undefined') {
        out.states.P1.reports[rep] = rp.data.data || [];
      } else { note('P1 ' + rep + ' failed'); }
    }

    // ── D7 + D90: whole-page state for other ranges ────────────────────────
    out.states.RANGES = {};
    var wanted = out.meta.datepicker.presets.filter(function (p) {
      return !p.disabled && /7 day|90 day/i.test(p.label);
    });
    for (var d = 0; d < wanted.length; d++) {
      var pr = wanted[d];
      var rd = await post({ action: 'wpforms_dashboard_get_stats', nonce: nonce, date: pr.value });
      if (rd && rd.success && rd.data) {
        out.states.RANGES[pr.preset || pr.label] = {
          date: pr.value, label: pr.label,
          chosenFilter: rd.data.chosen_filter || '',
          stats: rd.data.stats || null,
          payments: rd.data.payments || null,
          entriesHtml: rd.data.entries_html || '',
          locationsHtml: rd.data.locations_html || ''
        };
      } else { note('range ' + pr.value + ' failed'); }
    }

    out.meta.scrollHeightEnd = document.body.scrollHeight;
  } catch (e) {
    note('top:' + (e && e.message ? e.message : String(e)));
  }

  document.body.setAttribute('data-wpf-dashboard', JSON.stringify(out));
  return 'harvest done — err=' + (out.err || 'none') + ' scrollHeight=' + out.meta.scrollHeight;
})()
